// node --test scripts/tenant-manifest.test.mjs
//
// DE-29 done-when: gen-tenants --check passes on the tree and fails after a
// hand edit of a generated file; check-tenant-manifest passes on the tree and
// fails for each fixture (a manifest role with no Cedar file, a tenant with no
// requireTenant mount).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, writeFileSync, rmSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkTenantManifest } from './check-tenant-manifest.mjs';
import { validateManifest } from './gen-tenants.mjs';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..');
const FILES = [
  'tenants/manifest.json',
  'middleware/src/index.ts',
  'middleware/src/lib/tenants.generated.ts',
  'portal/src/lib/tenants.generated.ts',
  'infra/lib/tenants.generated.ts',
  'schema/identity_schema.sql',
  'portal/src/App.tsx',
  'portal/src/components/shell/Layout.tsx',
  'portal/src/pages/SelectContextPage.tsx',
];

function fixture() {
  const root = mkdtempSync(join(tmpdir(), 'de29-'));
  for (const f of FILES) { mkdirSync(dirname(join(root, f)), { recursive: true }); cpSync(join(REPO, f), join(root, f)); }
  cpSync(join(REPO, 'middleware/seeds/roles'), join(root, 'middleware/seeds/roles'), { recursive: true });
  return root;
}
const gen = (root, ...args) => spawnSync(process.execPath, [join(REPO, 'scripts/gen-tenants.mjs'), '--root', root, ...args], { encoding: 'utf8' });
const edit = (root, rel, fn) => writeFileSync(join(root, rel), fn(readFileSync(join(root, rel), 'utf8')));

test('the tree agrees with its manifest', () => {
  assert.equal(gen(REPO, '--check').status, 0);
  assert.deepEqual(checkTenantManifest(REPO), []);
});

test('gen --check exits 1 after a generated file is edited by hand, and a write restores it', () => {
  const root = fixture();
  try {
    edit(root, 'middleware/src/lib/tenants.generated.ts', s => s.replace("'pipelines', 'access'] as const;", "'pipelines'] as const;"));
    const r = gen(root, '--check');
    assert.equal(r.status, 1);
    assert.match(r.stderr, /middleware\/src\/lib\/tenants\.generated\.ts differs/);
    assert.equal(gen(root).status, 0);
    assert.equal(gen(root, '--check').status, 0);
    assert.equal(readFileSync(join(root, 'middleware/src/lib/tenants.generated.ts'), 'utf8'), readFileSync(join(REPO, 'middleware/src/lib/tenants.generated.ts'), 'utf8'));
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('the identity_schema.sql block is generated byte-for-byte as it was hand-written', () => {
  const sql = readFileSync(join(REPO, 'schema/identity_schema.sql'), 'utf8');
  assert.ok(sql.includes(`INSERT INTO tenants (id, display_name) VALUES
  ('orgiq', 'Work'),
  ('assessment', 'Assessment'),
  ('social', 'Social'),
  ('pipelines', 'Pipelines'),
  ('access', 'Access')
ON CONFLICT (id) DO NOTHING;`));
});

test('fixture: a manifest role with no Cedar file', () => {
  const root = fixture();
  try {
    edit(root, 'tenants/manifest.json', s => s.replace('"access-admin"]', '"access-admin", "auditor"]'));
    assert.equal(gen(root).status, 0); // regenerate, so only the seeds disagree
    const problems = checkTenantManifest(root);
    assert.ok(problems.some(p => p.includes('seeds/roles/access/auditor.cedar: manifest role has no Cedar file')), problems.join('\n'));
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('fixture: a Cedar file the manifest does not list, and an unregistered tenant directory', () => {
  const root = fixture();
  try {
    writeFileSync(join(root, 'middleware/seeds/roles/social/lurker.cedar'), '// fixture\n');
    mkdirSync(join(root, 'middleware/seeds/roles/phantom'));
    const problems = checkTenantManifest(root);
    assert.ok(problems.some(p => p.includes('social/lurker.cedar: role not listed')), problems.join('\n'));
    assert.ok(problems.some(p => p.includes('seeds/roles/phantom/: tenant directory not registered')), problems.join('\n'));
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('fixture: a tenant with no requireTenant mount', () => {
  const root = fixture();
  try {
    edit(root, 'middleware/src/index.ts', s => s.replace(/^app\.use\('\/api\/pipelines[^\n]*\n/gm, ''));
    const problems = checkTenantManifest(root);
    assert.deepEqual(problems, ["middleware/src/index.ts: no app.use('/api/pipelines', requireTenant('pipelines')…) mount"]);
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('fixture: a missing route tree and a drifted shell label', () => {
  const root = fixture();
  try {
    edit(root, 'portal/src/App.tsx', s => s.replace('path="access"', 'path="acess"'));
    edit(root, 'portal/src/components/shell/Layout.tsx', s => s.replace("  access: 'Access',", "  access: 'Access requests',"));
    const problems = checkTenantManifest(root);
    assert.ok(problems.includes('portal/src/App.tsx: no path="access" route tree for access'), problems.join('\n'));
    assert.ok(problems.includes("portal/src/components/shell/Layout.tsx: TENANT_LABELS lacks access: 'Access'"), problems.join('\n'));
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('the manifest validator refuses malformed entries', () => {
  const m = JSON.parse(readFileSync(join(REPO, 'tenants/manifest.json'), 'utf8'));
  assert.deepEqual(validateManifest(m), []);
  const bad = structuredClone(m);
  bad.tenants[1].home = '/iq/teams';
  bad.tenants[2].roles.push('member');
  bad.tenants[3].featureFlag = 'ENABLE_PIPELINES';
  bad.tenants[4].colour = 'teal';
  const errs = validateManifest(bad);
  assert.ok(errs.some(e => e.includes('(assessment): home must sit under portalRoot')));
  assert.ok(errs.some(e => e.includes('role "member" is declared twice')));
  assert.ok(errs.some(e => e.includes('(pipelines): featureFlag')));
  assert.ok(errs.some(e => e.includes('(access): unknown key "colour"')));
});
